-- Maintenance procedures for applications, domains, areas, roles, users, and modules.
USE `cxView`;

DROP PROCEDURE IF EXISTS `SP_TAS002_CREAR_APLICACION`;
DROP PROCEDURE IF EXISTS `SP_TAS002_ACTUALIZAR_APLICACION`;
DROP PROCEDURE IF EXISTS `SP_TAS002_DAR_BAJA_APLICACION`;
DROP PROCEDURE IF EXISTS `SP_TAS002_CONSULTAR_APLICACIONES`;
DROP PROCEDURE IF EXISTS `SP_TAS003_CREAR_DOMINIO`;
DROP PROCEDURE IF EXISTS `SP_TAS003_ACTUALIZAR_DOMINIO`;
DROP PROCEDURE IF EXISTS `SP_TAS003_DAR_BAJA_DOMINIO`;
DROP PROCEDURE IF EXISTS `SP_TAS003_CONSULTAR_DOMINIOS`;
DROP PROCEDURE IF EXISTS `SP_TAS004_CREAR_AREA`;
DROP PROCEDURE IF EXISTS `SP_TAS004_ACTUALIZAR_AREA`;
DROP PROCEDURE IF EXISTS `SP_TAS004_DAR_BAJA_AREA`;
DROP PROCEDURE IF EXISTS `SP_TAS004_CONSULTAR_AREAS`;
DROP PROCEDURE IF EXISTS `SP_TAS005_CREAR_ROL`;
DROP PROCEDURE IF EXISTS `SP_TAS005_ACTUALIZAR_ROL`;
DROP PROCEDURE IF EXISTS `SP_TAS005_DAR_BAJA_ROL`;
DROP PROCEDURE IF EXISTS `SP_TAS005_CONSULTAR_ROLES`;
DROP PROCEDURE IF EXISTS `SP_TAS006_CREAR_USUARIO`;
DROP PROCEDURE IF EXISTS `SP_TAS006_ACTUALIZAR_USUARIO`;
DROP PROCEDURE IF EXISTS `SP_TAS006_DAR_BAJA_USUARIO`;
DROP PROCEDURE IF EXISTS `SP_TAS006_CONSULTAR_USUARIOS`;
DROP PROCEDURE IF EXISTS `SP_TAS007_CREAR_MODULO`;
DROP PROCEDURE IF EXISTS `SP_TAS007_ACTUALIZAR_MODULO`;
DROP PROCEDURE IF EXISTS `SP_TAS007_DAR_BAJA_MODULO`;
DROP PROCEDURE IF EXISTS `SP_TAS007_CONSULTAR_MODULOS`;

DELIMITER $$
CREATE PROCEDURE `SP_TAS002_CREAR_APLICACION`(IN idempresa varchar(36), IN aplicacion varchar(50), IN descripcion varchar(200), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN
  SET @id = UUID(); INSERT INTO `TAS002` (`IDAPP`,`IDEMPRESA`,`NOMAPP`,`DESCAPP`,`ESTAPP`,`SACRG`,`CUSCRT`,`FCHHRACRT`) VALUES (@id,TRIM(idempresa),TRIM(aplicacion),NULLIF(TRIM(descripcion),''),'A',1,NULLIF(TRIM(usuario),''),CURRENT_TIMESTAMP(6));
  SELECT * FROM `TAS002` WHERE `IDAPP`=@id;
END$$
CREATE PROCEDURE `SP_TAS002_ACTUALIZAR_APLICACION`(IN idapp varchar(36), IN idempresa varchar(36), IN aplicacion varchar(50), IN descripcion varchar(200), IN estado varchar(1), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN
  UPDATE `TAS002` SET `IDEMPRESA`=TRIM(idempresa),`NOMAPP`=TRIM(aplicacion),`DESCAPP`=NULLIF(TRIM(descripcion),''),`ESTAPP`=UPPER(TRIM(estado)),`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDAPP`=TRIM(idapp) AND `SACRG`=1;
  SELECT * FROM `TAS002` WHERE `IDAPP`=TRIM(idapp) AND `SACRG`=1;
END$$
CREATE PROCEDURE `SP_TAS002_DAR_BAJA_APLICACION`(IN idapp varchar(36), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS002` SET `ESTAPP`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDAPP`=TRIM(idapp) AND `SACRG`=1; SELECT ROW_COUNT() AS `FILASAFECTADAS`; END$$
CREATE PROCEDURE `SP_TAS002_CONSULTAR_APLICACIONES`(IN idapp varchar(36), IN idempresa varchar(36), IN aplicacion varchar(50), IN estado varchar(1)) READS SQL DATA BEGIN SELECT * FROM `TAS002` WHERE `SACRG`=1 AND (NULLIF(TRIM(idapp),'') IS NULL OR `IDAPP`=TRIM(idapp)) AND (NULLIF(TRIM(idempresa),'') IS NULL OR `IDEMPRESA`=TRIM(idempresa)) AND (NULLIF(TRIM(aplicacion),'') IS NULL OR `NOMAPP` LIKE CONCAT('%',TRIM(aplicacion),'%')) AND (NULLIF(TRIM(estado),'') IS NULL OR `ESTAPP`=UPPER(TRIM(estado))) ORDER BY `NOMAPP`; END$$

CREATE PROCEDURE `SP_TAS003_CREAR_DOMINIO`(IN idempresa varchar(36), IN dominio varchar(50), IN descripcion varchar(100), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN SET @id=UUID(); INSERT INTO `TAS003` (`IDDOM`,`IDEMPRESA`,`NOMDOM`,`DESCDOM`,`ESTDOM`,`SACRG`,`CUSCRT`,`FCHHRACRT`) VALUES (@id,TRIM(idempresa),TRIM(dominio),NULLIF(TRIM(descripcion),''),'A',1,NULLIF(TRIM(usuario),''),CURRENT_TIMESTAMP(6)); SELECT * FROM `TAS003` WHERE `IDDOM`=@id; END$$
CREATE PROCEDURE `SP_TAS003_ACTUALIZAR_DOMINIO`(IN iddominio varchar(36), IN idempresa varchar(36), IN dominio varchar(50), IN descripcion varchar(100), IN estado varchar(1), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS003` SET `IDEMPRESA`=TRIM(idempresa),`NOMDOM`=TRIM(dominio),`DESCDOM`=NULLIF(TRIM(descripcion),''),`ESTDOM`=UPPER(TRIM(estado)),`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDDOM`=TRIM(iddominio) AND `SACRG`=1; SELECT * FROM `TAS003` WHERE `IDDOM`=TRIM(iddominio) AND `SACRG`=1; END$$
CREATE PROCEDURE `SP_TAS003_DAR_BAJA_DOMINIO`(IN iddominio varchar(36), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS003` SET `ESTDOM`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDDOM`=TRIM(iddominio) AND `SACRG`=1; SELECT ROW_COUNT() AS `FILASAFECTADAS`; END$$
CREATE PROCEDURE `SP_TAS003_CONSULTAR_DOMINIOS`(IN iddominio varchar(36), IN idempresa varchar(36), IN dominio varchar(50), IN estado varchar(1)) READS SQL DATA BEGIN SELECT * FROM `TAS003` WHERE `SACRG`=1 AND (NULLIF(TRIM(iddominio),'') IS NULL OR `IDDOM`=TRIM(iddominio)) AND (NULLIF(TRIM(idempresa),'') IS NULL OR `IDEMPRESA`=TRIM(idempresa)) AND (NULLIF(TRIM(dominio),'') IS NULL OR `NOMDOM` LIKE CONCAT('%',TRIM(dominio),'%')) AND (NULLIF(TRIM(estado),'') IS NULL OR `ESTDOM`=UPPER(TRIM(estado))) ORDER BY `NOMDOM`; END$$

CREATE PROCEDURE `SP_TAS004_CREAR_AREA`(IN idempresa varchar(36), IN area varchar(50), IN descripcion varchar(100), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN SET @id=UUID(); INSERT INTO `TAS004` (`IDAREA`,`IDEMPRESA`,`NOMAREA`,`DESCAREA`,`ESTAREA`,`SACRG`,`CUSCRT`,`FCHHRACRT`) VALUES (@id,TRIM(idempresa),TRIM(area),NULLIF(TRIM(descripcion),''),'A',1,NULLIF(TRIM(usuario),''),CURRENT_TIMESTAMP(6)); SELECT * FROM `TAS004` WHERE `IDAREA`=@id; END$$
CREATE PROCEDURE `SP_TAS004_ACTUALIZAR_AREA`(IN idarea varchar(36), IN idempresa varchar(36), IN area varchar(50), IN descripcion varchar(100), IN estado varchar(1), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS004` SET `IDEMPRESA`=TRIM(idempresa),`NOMAREA`=TRIM(area),`DESCAREA`=NULLIF(TRIM(descripcion),''),`ESTAREA`=UPPER(TRIM(estado)),`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDAREA`=TRIM(idarea) AND `SACRG`=1; SELECT * FROM `TAS004` WHERE `IDAREA`=TRIM(idarea) AND `SACRG`=1; END$$
CREATE PROCEDURE `SP_TAS004_DAR_BAJA_AREA`(IN idarea varchar(36), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS004` SET `ESTAREA`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDAREA`=TRIM(idarea) AND `SACRG`=1; SELECT ROW_COUNT() AS `FILASAFECTADAS`; END$$
CREATE PROCEDURE `SP_TAS004_CONSULTAR_AREAS`(IN idarea varchar(36), IN idempresa varchar(36), IN area varchar(50), IN estado varchar(1)) READS SQL DATA BEGIN SELECT * FROM `TAS004` WHERE `SACRG`=1 AND (NULLIF(TRIM(idarea),'') IS NULL OR `IDAREA`=TRIM(idarea)) AND (NULLIF(TRIM(idempresa),'') IS NULL OR `IDEMPRESA`=TRIM(idempresa)) AND (NULLIF(TRIM(area),'') IS NULL OR `NOMAREA` LIKE CONCAT('%',TRIM(area),'%')) AND (NULLIF(TRIM(estado),'') IS NULL OR `ESTAREA`=UPPER(TRIM(estado))) ORDER BY `NOMAREA`; END$$

CREATE PROCEDURE `SP_TAS005_CREAR_ROL`(IN idarea varchar(36), IN rol varchar(50), IN descripcion varchar(100), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN SET @id=UUID(); INSERT INTO `TAS005` (`IDROLEMP`,`IDAREA`,`NOMROL`,`DESCROL`,`ESTROL`,`SACRG`,`CUSCRT`,`FCHHRACRT`) VALUES (@id,TRIM(idarea),TRIM(rol),NULLIF(TRIM(descripcion),''),'A',1,NULLIF(TRIM(usuario),''),CURRENT_TIMESTAMP(6)); SELECT * FROM `TAS005` WHERE `IDROLEMP`=@id; END$$
CREATE PROCEDURE `SP_TAS005_ACTUALIZAR_ROL`(IN idrol varchar(36), IN idarea varchar(36), IN rol varchar(50), IN descripcion varchar(100), IN estado varchar(1), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS005` SET `IDAREA`=TRIM(idarea),`NOMROL`=TRIM(rol),`DESCROL`=NULLIF(TRIM(descripcion),''),`ESTROL`=UPPER(TRIM(estado)),`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDROLEMP`=TRIM(idrol) AND `SACRG`=1; SELECT * FROM `TAS005` WHERE `IDROLEMP`=TRIM(idrol) AND `SACRG`=1; END$$
CREATE PROCEDURE `SP_TAS005_DAR_BAJA_ROL`(IN idrol varchar(36), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS005` SET `ESTROL`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDROLEMP`=TRIM(idrol) AND `SACRG`=1; SELECT ROW_COUNT() AS `FILASAFECTADAS`; END$$
CREATE PROCEDURE `SP_TAS005_CONSULTAR_ROLES`(IN idrol varchar(36), IN idarea varchar(36), IN rol varchar(50), IN estado varchar(1)) READS SQL DATA BEGIN SELECT * FROM `TAS005` WHERE `SACRG`=1 AND (NULLIF(TRIM(idrol),'') IS NULL OR `IDROLEMP`=TRIM(idrol)) AND (NULLIF(TRIM(idarea),'') IS NULL OR `IDAREA`=TRIM(idarea)) AND (NULLIF(TRIM(rol),'') IS NULL OR `NOMROL` LIKE CONCAT('%',TRIM(rol),'%')) AND (NULLIF(TRIM(estado),'') IS NULL OR `ESTROL`=UPPER(TRIM(estado))) ORDER BY `NOMROL`; END$$

CREATE PROCEDURE `SP_TAS006_CREAR_USUARIO`(IN iddominio varchar(36), IN idrol varchar(36), IN login varchar(20), IN clave varbinary(128), IN nombres varchar(50), IN apepat varchar(50), IN apemat varchar(50), IN email varchar(50), IN cambiaclave tinyint, IN multiplesedes tinyint, IN sededefecto varchar(36), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN SET @id=UUID(); INSERT INTO `TAS006` (`IDUSER`,`IDDOMINIO`,`IDROLEMP`,`USUARIO`,`CLAVE`,`NOMBRES`,`APEPAT`,`APEMAT`,`EMAIL`,`ESTUSER`,`FLGACTPASS`,`FLGMLTSEDE`,`IDSEDEDEFAULT`,`SACRG`,`CUSCRT`,`FCHHRACRT`) VALUES (@id,NULLIF(TRIM(iddominio),''),NULLIF(TRIM(idrol),''),TRIM(login),clave,NULLIF(TRIM(nombres),''),NULLIF(TRIM(apepat),''),NULLIF(TRIM(apemat),''),NULLIF(TRIM(email),''),'A',COALESCE(cambiaclave,1),COALESCE(multiplesedes,0),NULLIF(TRIM(sededefecto),''),1,NULLIF(TRIM(usuario),''),CURRENT_TIMESTAMP(6)); SELECT `IDUSER`,`IDDOMINIO`,`IDROLEMP`,`USUARIO`,`NOMBRES`,`APEPAT`,`APEMAT`,`EMAIL`,`ESTUSER`,`FLGACTPASS`,`FLGMLTSEDE`,`IDSEDEDEFAULT`,`SACRG`,`CUSCRT`,`FCHHRACRT`,`CULUSA`,`FCHHRAACT` FROM `TAS006` WHERE `IDUSER`=@id; END$$
CREATE PROCEDURE `SP_TAS006_ACTUALIZAR_USUARIO`(IN iduser varchar(36), IN iddominio varchar(36), IN idrol varchar(36), IN login varchar(20), IN clave varbinary(128), IN nombres varchar(50), IN apepat varchar(50), IN apemat varchar(50), IN email varchar(50), IN estado varchar(1), IN cambiaclave tinyint, IN multiplesedes tinyint, IN sededefecto varchar(36), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS006` SET `IDDOMINIO`=NULLIF(TRIM(iddominio),''),`IDROLEMP`=NULLIF(TRIM(idrol),''),`USUARIO`=TRIM(login),`CLAVE`=COALESCE(clave,`CLAVE`),`NOMBRES`=NULLIF(TRIM(nombres),''),`APEPAT`=NULLIF(TRIM(apepat),''),`APEMAT`=NULLIF(TRIM(apemat),''),`EMAIL`=NULLIF(TRIM(email),''),`ESTUSER`=UPPER(TRIM(estado)),`FLGACTPASS`=COALESCE(cambiaclave,`FLGACTPASS`),`FLGMLTSEDE`=COALESCE(multiplesedes,`FLGMLTSEDE`),`IDSEDEDEFAULT`=NULLIF(TRIM(sededefecto),''),`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDUSER`=TRIM(iduser) AND `SACRG`=1; SELECT `IDUSER`,`IDDOMINIO`,`IDROLEMP`,`USUARIO`,`NOMBRES`,`APEPAT`,`APEMAT`,`EMAIL`,`ESTUSER`,`FLGACTPASS`,`FLGMLTSEDE`,`IDSEDEDEFAULT`,`SACRG`,`CUSCRT`,`FCHHRACRT`,`CULUSA`,`FCHHRAACT` FROM `TAS006` WHERE `IDUSER`=TRIM(iduser) AND `SACRG`=1; END$$
CREATE PROCEDURE `SP_TAS006_DAR_BAJA_USUARIO`(IN iduser varchar(36), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS006` SET `ESTUSER`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDUSER`=TRIM(iduser) AND `SACRG`=1; SELECT ROW_COUNT() AS `FILASAFECTADAS`; END$$
CREATE PROCEDURE `SP_TAS006_CONSULTAR_USUARIOS`(IN iduser varchar(36), IN iddominio varchar(36), IN idrol varchar(36), IN login varchar(20), IN email varchar(50), IN estado varchar(1)) READS SQL DATA BEGIN SELECT `IDUSER`,`IDDOMINIO`,`IDROLEMP`,`USUARIO`,`NOMBRES`,`APEPAT`,`APEMAT`,`EMAIL`,`ESTUSER`,`FLGACTPASS`,`FLGMLTSEDE`,`IDSEDEDEFAULT`,`SACRG`,`CUSCRT`,`FCHHRACRT`,`CULUSA`,`FCHHRAACT` FROM `TAS006` WHERE `SACRG`=1 AND (NULLIF(TRIM(iduser),'') IS NULL OR `IDUSER`=TRIM(iduser)) AND (NULLIF(TRIM(iddominio),'') IS NULL OR `IDDOMINIO`=TRIM(iddominio)) AND (NULLIF(TRIM(idrol),'') IS NULL OR `IDROLEMP`=TRIM(idrol)) AND (NULLIF(TRIM(login),'') IS NULL OR `USUARIO` LIKE CONCAT('%',TRIM(login),'%')) AND (NULLIF(TRIM(email),'') IS NULL OR `EMAIL` LIKE CONCAT('%',TRIM(email),'%')) AND (NULLIF(TRIM(estado),'') IS NULL OR `ESTUSER`=UPPER(TRIM(estado))) ORDER BY `USUARIO`; END$$

CREATE PROCEDURE `SP_TAS007_CREAR_MODULO`(IN idapp varchar(36), IN modulo varchar(50), IN descripcion varchar(100), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN SET @id=UUID(); INSERT INTO `TAS007` (`IDMOD`,`IDAPP`,`NOMMOD`,`DESCMOD`,`ESTMOD`,`SACRG`,`CUSCRT`,`FCHHRACRT`) VALUES (@id,TRIM(idapp),TRIM(modulo),NULLIF(TRIM(descripcion),''),'A',1,NULLIF(TRIM(usuario),''),CURRENT_TIMESTAMP(6)); SELECT * FROM `TAS007` WHERE `IDMOD`=@id; END$$
CREATE PROCEDURE `SP_TAS007_ACTUALIZAR_MODULO`(IN idmodulo varchar(36), IN idapp varchar(36), IN modulo varchar(50), IN descripcion varchar(100), IN estado varchar(1), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS007` SET `IDAPP`=TRIM(idapp),`NOMMOD`=TRIM(modulo),`DESCMOD`=NULLIF(TRIM(descripcion),''),`ESTMOD`=UPPER(TRIM(estado)),`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDMOD`=TRIM(idmodulo) AND `SACRG`=1; SELECT * FROM `TAS007` WHERE `IDMOD`=TRIM(idmodulo) AND `SACRG`=1; END$$
CREATE PROCEDURE `SP_TAS007_DAR_BAJA_MODULO`(IN idmodulo varchar(36), IN usuario varchar(20)) MODIFIES SQL DATA BEGIN UPDATE `TAS007` SET `ESTMOD`='I',`SACRG`=0,`CULUSA`=NULLIF(TRIM(usuario),''),`FCHHRAACT`=CURRENT_TIMESTAMP(6) WHERE `IDMOD`=TRIM(idmodulo) AND `SACRG`=1; SELECT ROW_COUNT() AS `FILASAFECTADAS`; END$$
CREATE PROCEDURE `SP_TAS007_CONSULTAR_MODULOS`(IN idmodulo varchar(36), IN idapp varchar(36), IN modulo varchar(50), IN estado varchar(1)) READS SQL DATA BEGIN SELECT * FROM `TAS007` WHERE `SACRG`=1 AND (NULLIF(TRIM(idmodulo),'') IS NULL OR `IDMOD`=TRIM(idmodulo)) AND (NULLIF(TRIM(idapp),'') IS NULL OR `IDAPP`=TRIM(idapp)) AND (NULLIF(TRIM(modulo),'') IS NULL OR `NOMMOD` LIKE CONCAT('%',TRIM(modulo),'%')) AND (NULLIF(TRIM(estado),'') IS NULL OR `ESTMOD`=UPPER(TRIM(estado))) ORDER BY `NOMMOD`; END$$
DELIMITER ;
